from pathlib import Path
from PIL import Image,ImageDraw
import json,hashlib
B=Path(__file__).resolve().parent;ROOT=B.parents[1];D=B/'fix06';D.mkdir(parents=True,exist_ok=True)
source=B/'fix04/generated.png';south=ROOT.parent/'northwest/r05_c04/native/s01_01.png'
im=Image.open(source).convert('RGBA');im.paste(Image.open(south).convert('RGBA').crop((0,0,1254,230)),(0,1024))
alpha=im.getchannel('A');ImageDraw.Draw(alpha).rectangle((620,0,1120,1023),fill=0);im.putalpha(alpha)
target=D/'masked-upper-rail-target.png'
if target.exists():raise FileExistsError(target)
im.save(target)
band=B/'fix04/real-south-top230.png'
prompt='''Use case: precise-object-edit. Fill the TRANSPARENT RECTANGLE in image1 with the missing continuation of this existing pale stone balustrade and stairway. The result must be fully opaque1254x1254. Image2 is the actual real native southern edge: it is already present in the bottom230rows of image1 and must stay fixed.
The hole is ONLY x620..1120,y0..1023. Rebuild that missing upper region by continuing the long vertical pale stone rail upward from its visible base at the bottom of the hole. Match both outside edges and both inset grooves directly to the base. The rail outer RIGHT edge meets the base at x1004; its RIGHT inset groove at x917. Its left edge must connect to the existing base near x670. This is one long plain inset running through the top and bottom image edges, with no end cap and no ornamental panel. Continue stairs on its right to the already visible right-hand stair fragments, preserving their established tread cadence.
Keep every existing opaque pixel outside the hole unchanged, especially the complete bottom230rows, the green carving fragment at the bottom, all left pedestal stone faces and the far-right stair strips. Do not move or rescale the canvas. No extra objects, text, UI, people or watermark. Match the smooth rounded hand-painted pale stone and bright daylight exactly. Fill only the transparent gap, do not redesign any existing shape.'''
p={'prompt':prompt,'referenced_image_paths':[str(target),str(band)],'transparent_background':False}
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
(D/'parameters.json').write_text(json.dumps(p,indent=2),encoding='utf-8');(D/'prompt.txt').write_text(prompt,encoding='utf-8')
(D/'preparation.json').write_text(json.dumps({'source':str(source),'sourceSha256':sha(source),'actualSouthSource':str(south),'actualSouthSha256':sha(south),
'southSourceCrop':[0,0,1254,230],'targetPaste':[0,1024,1254,1254],'editMaskRect':[620,0,1121,1024],'maskOnly':True,
'operation':'Preparation only: exact native context crop/paste and alpha edit mask; final pixels must be generated by image_gen; no code-rendered artwork',
'submittedTarget':str(target),'submittedTargetSha256':sha(target),'sourceResampled':False,'guideGameArt':False,'actualModel':None,'actualQuality':None},indent=2),encoding='utf-8')
